/* Globall Cloud — invoice template workflow matching Globall_Cloud_Invoice_Blank. */
(() => {
  'use strict';
  const SUPABASE_URL = 'https://ahslifnthiwfkmaswjno.supabase.co';
  const API = `${SUPABASE_URL}/functions/v1/logistics-control-plane`;
  const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const n = (v) => Number.isFinite(Number(v)) ? Number(v) : 0;
  const money = (v, currency = 'USD') => `${n(v).toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})} ${currency}`;
  const today = () => new Date().toISOString().slice(0, 10);
  const session = async () => (await window.sb?.auth?.getSession?.())?.data?.session || null;
  const post = async (action, data) => {
    const s = await session(); if (!s?.access_token) throw new Error('تکایە دووبارە بچۆ ژوورەوەی Staff Console.');
    const r = await fetch(API, {method:'POST', headers:{apikey: window.gcSupabaseConfig?.publishableKey || '', Authorization:`Bearer ${s.access_token}`, 'Content-Type':'application/json'}, body:JSON.stringify({action, data}), cache:'no-store'});
    const d = await r.json().catch(() => ({})); if (!r.ok) throw new Error(d.error || `Invoice HTTP ${r.status}`); return d.item || d;
  };
  const openModal = (body, footer) => { document.getElementById('gcInvoiceModal')?.remove(); const x=document.createElement('div'); x.id='gcInvoiceModal'; x.className='gc-invoice-modal'; x.innerHTML=`<div class="gc-invoice-modal-card"><div class="gc-invoice-modal-head"><div><span>GLOBALL CLOUD · FINANCE</span><h2>دروستکردنی Invoice</h2></div><button type="button" data-invoice-close>×</button></div>${body}<div class="gc-invoice-modal-foot">${footer}</div></div>`; document.body.appendChild(x); x.addEventListener('click',e=>{if(e.target===x||e.target.closest('[data-invoice-close]'))x.remove()}); return x; };
  const line = (i=0) => `<div class="gc-invoice-line" data-invoice-line><input name="description" placeholder="Item / Description" aria-label="Item / Description"><input name="quantity" type="number" min="0" step="0.01" value="1" placeholder="Qty"><input name="basis" placeholder="Basis" aria-label="Basis"><input name="unit_price" type="number" min="0" step="0.01" value="0" placeholder="Unit price"><output data-line-amount>0.00</output><button type="button" data-remove-line aria-label="Remove">×</button></div>`;
  const open = () => {
    const x=openModal(`<form id="gcInvoiceForm" class="gc-invoice-form"><div class="gc-invoice-grid"><label>Invoice number<input name="invoice_number" required value="INV/${new Date().getFullYear()}/"></label><label>Shipment ID<input name="shipment_id" required placeholder="GC-338"></label><label>Invoice date<input name="invoice_date" type="date" value="${today()}"></label><label>Due date<input name="due_at" type="date"></label><label>Receipt No.<input name="receipt_no" placeholder="Receipt reference"></label><label>Currency<select name="currency"><option>USD</option><option>IQD</option><option>AED</option><option>CNY</option><option>EUR</option></select></label><label>Bill to / Customer<input name="bill_to_name" placeholder="Customer name"></label><label>Shipping address<input name="bill_to_address" placeholder="Address"></label></div><div class="gc-invoice-lines-head"><strong>ITEM / DESCRIPTION</strong><strong>QTY</strong><strong>BASIS</strong><strong>UNIT PRICE</strong><strong>AMOUNT</strong><span></span></div><div id="gcInvoiceLines">${line()}</div><button type="button" class="btn" id="gcAddInvoiceLine">+ زیادکردنی item</button><div class="gc-invoice-totals"><label>Subtotal<input name="subtotal" type="number" step="0.01" value="0" readonly></label><label>Discount<input name="discount" type="number" min="0" step="0.01" value="0"></label><label>Additional charges<input name="additional_charges" type="number" min="0" step="0.01" value="0"></label><label>Amount paid<input name="amount_paid" type="number" min="0" step="0.01" value="0"></label><strong>Total USD <output id="gcInvoiceTotal">0.00</output></strong></div><div class="gc-invoice-grid"><label>Payment method / Notes<textarea name="payment_method" rows="2" placeholder="Cash, bank transfer, QiCard…"></textarea></label><label>Internal notes<textarea name="notes" rows="2" placeholder="Notes"></textarea></label></div><p id="gcInvoiceMsg" class="gc-invoice-msg" role="status"></p></form>`, '<button type="button" class="btn" data-invoice-close>هەڵوەشاندنەوە</button><button type="button" class="btn primary" id="gcSaveInvoice">پاشەکەوتکردن و چاپکردن</button>');
    const form=x.querySelector('#gcInvoiceForm'), lines=x.querySelector('#gcInvoiceLines');
    const calc=()=>{let subtotal=0; lines.querySelectorAll('[data-invoice-line]').forEach(row=>{const amount=n(row.querySelector('[name=quantity]').value)*n(row.querySelector('[name=unit_price]').value); subtotal+=amount; row.querySelector('[data-line-amount]').textContent=amount.toFixed(2)}); form.elements.subtotal.value=subtotal.toFixed(2); const total=Math.max(0,subtotal-n(form.elements.discount.value)+n(form.elements.additional_charges.value)); x.querySelector('#gcInvoiceTotal').textContent=total.toFixed(2); return {subtotal,total};};
    form.addEventListener('input',calc); x.querySelector('#gcAddInvoiceLine').onclick=()=>{lines.insertAdjacentHTML('beforeend',line()); calc()}; lines.addEventListener('click',e=>{if(e.target.closest('[data-remove-line]')){e.target.closest('[data-invoice-line]').remove();calc()}}); calc();
    x.querySelector('#gcSaveInvoice').onclick=async()=>{const b=x.querySelector('#gcSaveInvoice'),msg=x.querySelector('#gcInvoiceMsg'); b.disabled=true; msg.textContent='خەریکی پاشەکەوتکردنە…'; try{const {subtotal,total}=calc();const fd=new FormData(form);const items=[...lines.querySelectorAll('[data-invoice-line]')].map(r=>({description:r.querySelector('[name=description]').value.trim(),quantity:n(r.querySelector('[name=quantity]').value),basis:r.querySelector('[name=basis]').value.trim(),unit_price:n(r.querySelector('[name=unit_price]').value),amount:n(r.querySelector('[data-line-amount]').textContent)})).filter(i=>i.description||i.amount);const data={invoice_number:fd.get('invoice_number'),shipment_id:fd.get('shipment_id'),invoice_date:fd.get('invoice_date')||today(),due_at:fd.get('due_at')||null,receipt_no:fd.get('receipt_no'),bill_to_name:fd.get('bill_to_name'),bill_to_address:fd.get('bill_to_address'),currency:fd.get('currency'),payment_method:fd.get('payment_method'),notes:fd.get('notes'),line_items:items,subtotal,discount:n(fd.get('discount')),additional_charges:n(fd.get('additional_charges')),tax:0,status:'issued'};const invoice=await post('upsert_invoice',data);const paid=n(fd.get('amount_paid'));if(paid>0&&invoice?.id)await post('record_payment',{invoice_id:invoice.id,amount:paid,transaction_type:'payment',status:'succeeded',provider:'manual',method:fd.get('payment_method')||'manual',idempotency_key:`invoice-${invoice.id}-${Date.now()}`});msg.textContent='Invoice پاشەکەوت کرا.'; printInvoice({...data,...invoice,paid_total:paid,total});}catch(e){msg.textContent=e.message||'Invoice دروست نەکرا.';b.disabled=false}};
  };
  const printInvoice=(d)=>{const currency=esc(d.currency||'USD');const items=(d.line_items||[]).map(i=>`<tr><td>${esc(i.description||'')}</td><td>${esc(i.quantity||'')}</td><td>${esc(i.basis||'')}</td><td>${money(i.unit_price,currency)}</td><td>${money(i.amount,currency)}</td></tr>`).join('');const w=window.open('','_blank','noopener,noreferrer');if(!w){alert('Popup ـەکە ڕێگەپێنەدراوە؛ تکایە popup چالاک بکە.');return}w.document.write(`<!doctype html><html lang="en"><head><meta charset="utf-8"><title>${esc(d.invoice_number||'Invoice')}</title><style>@page{size:A4;margin:14mm}body{font-family:Arial,sans-serif;color:#12354e;margin:0;font-size:11px}.top{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:3px solid #0d8e98;padding-bottom:12px}.brand h1{margin:0;font-size:24px;color:#0b3553}.brand b{color:#0d8e98}.phones{text-align:right;font-weight:bold;line-height:1.6}.bar{margin-top:14px;background:#0a3555;color:#fff;padding:10px 14px;display:flex;justify-content:space-between;font-size:18px;font-weight:bold}.meta{display:grid;grid-template-columns:1fr 1fr;border:1px solid #b8cbd2;margin-top:12px;padding:12px;gap:8px}.meta b{display:block;color:#0d7f89;font-size:10px;text-transform:uppercase}.meta span{display:block;border-bottom:1px solid #98abb4;padding:3px 0}.items{width:100%;border-collapse:collapse;margin-top:30px}.items th{background:#0a3555;color:#fff;padding:8px;font-size:10px}.items td{border:1px solid #c8d5d8;padding:8px}.items tr:nth-child(even){background:#fff9e9}.totals{margin:12px 0 0 auto;width:42%;border-collapse:collapse}.totals td{padding:7px;border-bottom:1px solid #9db1b8}.totals td:last-child{text-align:right}.totals .total{background:#0d8e98;color:#fff;font-weight:bold;font-size:14px}.notes{border:1px solid #b8cbd2;margin-top:15px;padding:10px;min-height:52px}.sign{display:flex;justify-content:space-between;margin-top:45px}.sign span{border-top:1px solid #999;width:30%;padding-top:6px}.footer{border-top:1px solid #9db1b8;margin-top:36px;padding-top:10px;font-size:9px;color:#527080}.thanks{text-align:center;color:#0d8e98;font-weight:bold;margin-top:10px}@media print{button{display:none}}</style></head><body><div class="top"><div class="brand"><h1>GLOBALL CLOUD</h1><b>GLOBAL LOGISTICS</b><div>FOR GENERAL TRADING · IMPORT & EXPORT</div></div><div class="phones">0772 944 1884<br>0750 768 1884<br>0750 429 1341<br><small>WhatsApp / Viber</small></div></div><div class="bar"><span>INVOICE</span><span>${esc(d.invoice_number||'')}</span></div><div class="meta"><div><b>Bill to / Customer</b><span>${esc(d.bill_to_name||'')}</span><b>Shipping address</b><span>${esc(d.bill_to_address||'')}</span></div><div><b>Invoice date</b><span>${esc(d.invoice_date||'')}</span><b>Due date</b><span>${esc(d.due_at||'')}</span><b>Receipt No.</b><span>${esc(d.receipt_no||'')}</span></div></div><table class="items"><thead><tr><th>ITEM / DESCRIPTION</th><th>QUANTITY</th><th>BASIS</th><th>UNIT PRICE</th><th>AMOUNT</th></tr></thead><tbody>${items}</tbody></table><table class="totals"><tr><td>SUBTOTAL</td><td>${money(d.subtotal,currency)}</td></tr><tr><td>DISCOUNT</td><td>${money(d.discount,currency)}</td></tr><tr><td>ADDITIONAL CHARGES</td><td>${money(d.additional_charges,currency)}</td></tr><tr class="total"><td>TOTAL ${currency}</td><td>${money(d.total,currency)}</td></tr><tr><td>AMOUNT PAID</td><td>${money(d.paid_total,currency)}</td></tr><tr><td>BALANCE DUE</td><td>${money(Math.max(0,n(d.total)-n(d.paid_total)),currency)}</td></tr></table><div class="notes"><b>PAYMENT METHOD / NOTES</b><br>${esc(d.payment_method||'')}<br>${esc(d.notes||'')}</div><div class="sign"><span>Prepared / Authorized by</span><span>Customer Signature</span></div><div class="footer"><b>GLOBALL CLOUD · ERBIL - HAWLERI NWE, NEXT TO GASHA INSTITUTE</b><br>Hawler - Hawleri Nwe, Tanisht Paymangay Gasha · globalcloud@gmail.com · 0772 944 1884 · 0750 768 1884 · 0750 429 1341<div class="thanks">Thank you for your business with Globall Cloud.</div></div><script>setTimeout(()=>window.print(),250)<\/script></body></html>`);w.document.close()};
  const mount=()=>{const view=document.getElementById('view');if(!view||!/FINANCE CONTROL|دارایی/.test(view.textContent)||document.getElementById('gcInvoiceTemplateBtn'))return;const actions=view.querySelector('.section-head .actions');if(!actions)return;const b=document.createElement('button');b.id='gcInvoiceTemplateBtn';b.className='btn primary';b.textContent='+ Invoice ـی نوێ';b.onclick=open;actions.prepend(b)};
  new MutationObserver(mount).observe(document.body,{subtree:true,childList:true}); setInterval(mount,1200); mount();
})();
